function initModals() {
  document.querySelectorAll("[data-close]").forEach((button) => {
    button.addEventListener("click", () => {
      button.closest("dialog")?.close();
    });
  });
  document.querySelectorAll("dialog.sheet").forEach((dialog2) => {
    dialog2.addEventListener("close", () => routeAfterClose());
  });
  window.addEventListener("popstate", () => applyRoute());
  const searchInput = document.getElementById("searchInput");
  searchInput?.addEventListener("input", () => renderSearch());
  searchInput?.addEventListener("keydown", (event) => {
    const results = document.getElementById("searchResults");
    if (!results) return;
    const rows = [...results.querySelectorAll(".searchRow")];
    const index = rows.findIndex((row) => row.classList.contains("focused"));
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (rows.length === 0) return;
      const next = event.key === "ArrowDown" ? (index + 1) % rows.length : (index - 1 + rows.length) % rows.length;
      rows.forEach((row) => row.classList.remove("focused"));
      rows[next]?.classList.add("focused");
      rows[next]?.scrollIntoView({ block: "nearest" });
    } else if (event.key === "Enter") {
      event.preventDefault();
      (rows[index] ?? rows[0])?.click();
    }
  });
  document.querySelectorAll("#settingsNav button").forEach((button) => {
    button.addEventListener("click", () => {
      renderSettings(button.dataset.section ?? "general");
      syncRoute(true);
    });
  });
  const name = document.getElementById("newBotName");
  name?.addEventListener("input", () => {
    draft.name = name.value;
    if (!draft.touched) draft.avatar = null;
    setNewBotError("");
    paintNewBot();
  });
  name?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      void createBot();
    }
  });
  document.getElementById("createBot")?.addEventListener("click", () => void createBot());
  document.getElementById("saveAvatar")?.addEventListener("click", () => void saveAvatar());
  document.getElementById("rtAdd")?.addEventListener("click", () => void addRoutine());
  document.getElementById("agentSave")?.addEventListener("click", () => void saveAgent());
  const rtTitle = document.getElementById("rtTitle");
  rtTitle?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      void addRoutine();
    }
  });
  initGate();
  noteLoginFailure();
  document.addEventListener("keydown", (event) => {
    const modifier = event.metaKey || event.ctrlKey;
    if (modifier && event.key.toLowerCase() === "k") {
      event.preventDefault();
      openSearch();
    } else if (modifier && event.key.toLowerCase() === "n") {
      event.preventDefault();
      void openNewBot();
    } else if (modifier && event.key === ",") {
      event.preventDefault();
      openSettings();
    }
  });
}

